// @generated by:gauntlet run:godseye-local-hermes-chat
export function chatFrames(body: ReadableStream<Uint8Array>) {
  const reader = body.getReader(),
    decoder = new TextDecoder();
  let buffered = "";
  return {
    reader,
    async next() {
      const timer = setTimeout(() => {
        void reader.cancel("Bounded chat fixture deadline");
      }, 3000);
      try {
        while (true) {
          const boundary = buffered.indexOf("\n\n");
          if (boundary >= 0) {
            const raw = buffered.slice(0, boundary);
            buffered = buffered.slice(boundary + 2);
            const lines = raw.split("\n");
            const event = lines.find((line) => line.startsWith("event: "))?.slice(7);
            if (!event) continue;
            const data = lines
              .filter((line) => line.startsWith("data: "))
              .map((line) => line.slice(6))
              .join("\n");
            return {
              event,
              id: lines.find((line) => line.startsWith("id: "))?.slice(4),
              data: JSON.parse(data) as unknown,
            };
          }
          const part = await reader.read();
          if (part.done) return null;
          buffered += decoder.decode(part.value, { stream: true });
          if (buffered.length > 65536) throw new Error("Chat fixture frame exceeded its bound");
        }
      } finally {
        clearTimeout(timer);
      }
    },
  };
}
